import pyomo.environ as pyo

DATA = {
    "budget": 70000.0,
    "rates": {
        "municipal_bonds": 0.085,
        "cds": 0.05,
        "t_bills": 0.065,
        "growth_stocks": 0.13,
    },
    "max_muni_frac": 0.20,
    "min_tbill_cd_frac": 0.30,
    "ratio_cd_tbill_to_muni_growth": 1.2,
}


def build_model(data=None):
    d = data or DATA

    instruments = list(d["rates"].keys())
    m = pyo.ConcreteModel()

    m.I = pyo.Set(initialize=instruments, ordered=True)

    # Variables: dollars invested in each instrument, nonnegative, bounded by budget
    m.x = pyo.Var(
        m.I,
        domain=pyo.NonNegativeReals,
        bounds=(0.0, d["budget"]),
    )

    # Objective: maximize total profit (return rate * amount)
    def obj_rule(m):
        return sum(d["rates"][i] * m.x[i] for i in m.I)

    m.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Constraint 5: all budget invested
    def budget_rule(m):
        return sum(m.x[i] for i in m.I) == d["budget"]

    m.budget_con = pyo.Constraint(rule=budget_rule)

    # Constraint 1: no more than 20% in municipal bonds
    def max_muni_rule(m):
        return m.x["municipal_bonds"] <= d["max_muni_frac"] * d["budget"]

    m.max_muni_con = pyo.Constraint(rule=max_muni_rule)

    # Constraint 2: CDs <= municipal + t-bills + growth stocks
    def max_cds_rule(m):
        return m.x["cds"] <= (
            m.x["municipal_bonds"] + m.x["t_bills"] + m.x["growth_stocks"]
        )

    m.max_cds_con = pyo.Constraint(rule=max_cds_rule)

    # Constraint 3: at least 30% in t-bills and CDs
    def min_tbill_cd_rule(m):
        return m.x["t_bills"] + m.x["cds"] >= d["min_tbill_cd_frac"] * d["budget"]

    m.min_tbill_cd_con = pyo.Constraint(rule=min_tbill_cd_rule)

    # Constraint 4: CD + t-bills vs muni + growth in ratio 1.2 : 1
    def ratio_rule(m):
        return (m.x["cds"] + m.x["t_bills"]) >= d[
            "ratio_cd_tbill_to_muni_growth"
        ] * (m.x["municipal_bonds"] + m.x["growth_stocks"])

    m.ratio_con = pyo.Constraint(rule=ratio_rule)

    return m

import pyomo.environ as pyo

DATA = {
    "total_capital": 70000.0,
    "instruments": ["muni", "cd", "tbill", "growth"],
    "return_rate": {
        "muni": 0.085,
        "cd": 0.05,
        "tbill": 0.065,
        "growth": 0.13,
    },
    "muni_max_frac": 0.20,
    "tbill_cd_min_frac": 0.30,
    "ratio_cd_tbill": 1.2,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["instruments"])

    model.invest = pyo.Var(
        model.I,
        domain=pyo.NonNegativeReals,
        bounds=(0.0, d["total_capital"]),
    )

    def obj_rule(m):
        return sum(d["return_rate"][i] * m.invest[i] for i in m.I)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    def muni_cap_rule(m):
        return m.invest["muni"] <= d["muni_max_frac"] * d["total_capital"]

    model.muni_cap = pyo.Constraint(rule=muni_cap_rule)

    def cd_le_others_rule(m):
        return m.invest["cd"] <= m.invest["muni"] + m.invest["tbill"] + m.invest["growth"]

    model.cd_le_others = pyo.Constraint(rule=cd_le_others_rule)

    def tb_cd_min_rule(m):
        return m.invest["tbill"] + m.invest["cd"] >= d["tbill_cd_min_frac"] * d["total_capital"]

    model.tb_cd_min = pyo.Constraint(rule=tb_cd_min_rule)

    def ratio_rule(m):
        return m.invest["cd"] + m.invest["tbill"] >= d["ratio_cd_tbill"] * (
            m.invest["muni"] + m.invest["growth"]
        )

    model.ratio_cd_tbill = pyo.Constraint(rule=ratio_rule)

    def budget_rule(m):
        return sum(m.invest[i] for i in m.I) == d["total_capital"]

    model.budget = pyo.Constraint(rule=budget_rule)

    return model


